def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Handles None or empty inputs by returning 0.
    """
    if not nums:
        return 0
    # Ensure we have a sequence of comparable items
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []
    for x in nums:
        # Skip non-integer elements safely
        try:
            # compare using <
            _ = x < x  # will raise if not comparable
        except Exception:
            continue
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

