def solve(a, b):
    """Levenshtein edit distance between a and b with O(min(m,n)) space.
    Handles None inputs as empty strings.
    """
    if a is None:
        a = ''
    if b is None:
        b = ''
    if not isinstance(a, str):
        a = str(a)
    if not isinstance(b, str):
        b = str(b)
    if a == b:
        return 0
    m, n = len(a), len(b)
    # Ensure n <= m to use less space
    if n > m:
        a, b = b, a
        m, n = n, m
    # b is the shorter string now
    previous = list(range(n + 1))
    for i, ca in enumerate(a, 1):
        current = [i] + [0] * n
        for j, cb in enumerate(b, 1):
            cost = 0 if ca == cb else 1
            current[j] = min(previous[j] + 1,      # deletion
                               current[j-1] + 1,   # insertion
                               previous[j-1] + cost)  # substitution
        previous = current
    return previous[n]

