def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    tokens: list of strings, each either an integer (possibly negative) or one of '+', '-', '*', '/'.
    Division should truncate toward zero, as in int(a / b).
    Returns the integer result.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                # Python division of ints yields float; int() truncates toward zero.
                stack.append(int(a / b))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

