    Handles malformed intervals by ignoring them.
    Returns merged intervals sorted by start.
    """
    if not intervals:
        return []
    # Filter valid intervals: length 2 and start <= end
    valid = []
    for iv in intervals:
        try:
            if len(iv) != 2:
                continue
            s, e = iv[0], iv[1]
            if s <= e:
                valid.append([s, e])
        except Exception:
            continue
    if not valid:
        return []
    valid.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = valid[0]
    for s, e in valid[1:]:
        if s <= cur_end:  # overlap or touch
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

