def solve(matrix):
    """Return elements of the matrix in clockwise spiral order.
    Handles empty matrix and non‑rectangular inputs gracefully (assumes rectangular as per spec)."""
    if not matrix:
        return []
    rows, cols = len(matrix), len(matrix[0])
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    res = []
    while top <= bottom and left <= right:
        # traverse from left to right on the top row
        for c in range(left, right + 1):
            res.append(matrix[top][c])
        top += 1
        # traverse downwards on the right column
        for r in range(top, bottom + 1):
            res.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            # traverse from right to left on the bottom row
            for c in range(right, left - 1, -1):
                res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            # traverse upwards on the left column
            for r in range(bottom, top - 1, -1):
                res.append(matrix[r][left])
            left += 1
    return res

