            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]

