def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings: integers or '+', '-', '*', '/'. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Use absolute division to avoid float inaccuracies
                if b == 0:
                    raise ZeroDivisionError("division by zero in RPN expression")
                sign = -1 if (a * b) < 0 else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            stack.append(int(token))
    return stack[0]

